-- Quests that pay coins (generated by drizzle-kit from src/db/schema.ts, with one hand-written step: the seed at the end).
--
--  1. quests: the catalogue (slug, kind discord_link | discord_guild | visit, reward, active).
--  2. quest_progress: per account and quest, started_at (visit quests) and the claim. The primary key
--     (account_id, quest_id) and quest_progress_discord_uq (discord_user_id, quest_id) make a quest
--     pay once per account and once per Discord account; the claim's ledger entry uses the
--     idempotency key quest:<quest id>:<account id>, so a double claim can never pay twice.
--  3. wallet_ledger gains the reason `quest` (positive deltas only, wallet_ledger_sign).
CREATE TABLE "quest_progress" (
	"account_id" uuid NOT NULL,
	"quest_id" uuid NOT NULL,
	"started_at" timestamp with time zone,
	"claimed_at" timestamp with time zone,
	"discord_user_id" text,
	"ledger_id" bigint,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "quest_progress_account_id_quest_id_pk" PRIMARY KEY("account_id","quest_id"),
	CONSTRAINT "quest_progress_claim_complete" CHECK (("quest_progress"."claimed_at" is null) = ("quest_progress"."ledger_id" is null) and ("quest_progress"."claimed_at" is null) = ("quest_progress"."discord_user_id" is null))
);
--> statement-breakpoint
CREATE TABLE "quests" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"slug" text NOT NULL,
	"kind" text NOT NULL,
	"title" text NOT NULL,
	"description" text DEFAULT '' NOT NULL,
	"url" text,
	"reward_amount" bigint NOT NULL,
	"currency" text DEFAULT 'coins' NOT NULL,
	"active" boolean DEFAULT false NOT NULL,
	"sort" integer DEFAULT 0 NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "quests_slug_format" CHECK ("quests"."slug" ~ '^[a-z0-9][a-z0-9_]{1,47}$'),
	CONSTRAINT "quests_kind" CHECK ("quests"."kind" in ('discord_link', 'discord_guild', 'visit')),
	CONSTRAINT "quests_title_len" CHECK (length("quests"."title") between 1 and 80),
	CONSTRAINT "quests_description_len" CHECK (length("quests"."description") <= 500),
	CONSTRAINT "quests_url_format" CHECK ("quests"."url" is null or ("quests"."url" ~ '^https://[^[:space:]]+$' and length("quests"."url") <= 2048)),
	CONSTRAINT "quests_url_only_visit" CHECK ("quests"."kind" = 'visit' or "quests"."url" is null),
	CONSTRAINT "quests_active_visit_has_url" CHECK (not "quests"."active" or "quests"."kind" <> 'visit' or "quests"."url" is not null),
	CONSTRAINT "quests_reward_range" CHECK ("quests"."reward_amount" between 1 and 1000000),
	CONSTRAINT "quests_currency" CHECK ("quests"."currency" ~ '^[a-z][a-z0-9_]{1,15}$')
);
--> statement-breakpoint
